/* Hand-written cairo-features.h for wasm32-emscripten.
 *
 * Normally generated by cairo's configure. Written by hand because running an
 * archive's configure is not permitted here, and because the feature set we
 * want is deliberately tiny.
 *
 * Enabled: the image surface, the FreeType font backend (what norns uses via
 * cairo_ft_font_face_create_for_ft_face), PNG, user fonts, and the core
 * surface types whose sources are unconditionally part of cairo_sources.
 *
 * Deliberately DISABLED:
 *   CAIRO_HAS_FC_FONT  -- norns loads fonts by explicit path with FT_New_Face,
 *                         so fontconfig is dead weight. The emscripten-forge
 *                         prebuilt cairo forces it; building ourselves avoids
 *                         the dependency entirely.
 *   PS / PDF / SVG / SCRIPT / XML / XLIB / XCB / WIN32 / QUARTZ / GL / COGL /
 *   DRM / TEE / GOBJECT -- none reachable from the norns screen API.
 */
#ifndef CAIRO_FEATURES_H
#define CAIRO_FEATURES_H

#define CAIRO_HAS_IMAGE_SURFACE 1
#define CAIRO_HAS_FT_FONT 1
#define CAIRO_HAS_PNG_FUNCTIONS 1
#define CAIRO_HAS_USER_FONT 1
#define CAIRO_HAS_RECORDING_SURFACE 1
#define CAIRO_HAS_OBSERVER_SURFACE 1
#define CAIRO_HAS_MIME_SURFACE 1

#endif /* CAIRO_FEATURES_H */
